The structure:
- `seedFromString(s: string): bigint` - FNV-1a 64-bit
- `Rng` class:
  - Constructor takes a `bigint` seed
  - Uses splitmix64 to expand to 4 U32s
  - `nextU32()` - xoshiro128** next
  - `nextF64()` - divides nextU32 by 2^32
  - `nextRange(min, max)` - float in range
  - `nextInt(n)` - integer in [0, n)
  - `pick(arr)` - random element
  - `nextGauss(mean, sd)` - Box-Muller
- `hash2(a, b): bigint` - splitmix finalizer

Let me implement this carefully.

```typescript
// FNV-1a 64-bit
const FNV_OFFSET_BIG = 0xcbf29ce484222325n;
const FNV_PRIME_BIG = 0x100000001b3n;
const MASK_64 = (1n << 64n) - 1n;

export function seedFromString(s: string): bigint {
  const bytes = new TextEncoder().encode(s);
  let hash = FNV_OFFSET_BIG;
  for (const byte of bytes) {
    hash = ((hash ^ BigInt(byte)) * FNV_PRIME_BIG) & MASK_64;
  }
  return hash;
}
```

```typescript
const MASK_32 = 0xffffffffn;
const SPLITMIX64_INC = 0x9e3779b97f4a7c15n;

function splitmix64Next(state: bigint): { value: bigint; next: bigint } {
  let z = (state + SPLITMIX64_INC) & MASK_64;
  // z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9n
  z = ((z ^ (z >> 30n)) * 0xbf58476d1ce4e5b9n) & MASK_64;
  z = ((z ^ (z >> 27n)) * 0x94d049bb133111ebn) & MASK_64;
  z = z ^ (z >> 31n);
  return { value: z, next: z };
}
```

